package com.yuyutian.mytools.media.library.controller;
import com.yuyutian.mytools.media.library.config.MediaLibraryConfiguration.InternalToken;import com.yuyutian.mytools.media.library.model.MediaModels.*;import com.yuyutian.mytools.media.library.service.LegacyMediaContentService;import com.yuyutian.mytools.media.library.service.LegacyEbookProjectionService;import com.yuyutian.mytools.media.library.service.MediaLibraryService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.MediaType;import org.springframework.http.ResponseEntity;import org.springframework.core.io.Resource;import org.springframework.web.bind.annotation.*;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.UUID;
/** Media Library API。 */ @RestController public class MediaLibraryController {
 private final MediaLibraryService service;private final LegacyMediaContentService contentService;private final LegacyEbookProjectionService ebookService;private final InternalToken token;
 /** 创建控制器。 @param service 服务 @param contentService 内容服务 @param ebookService 电子书投影 @param token 令牌 */ public MediaLibraryController(MediaLibraryService service,LegacyMediaContentService contentService,LegacyEbookProjectionService ebookService,InternalToken token){this.service=service;this.contentService=contentService;this.ebookService=ebookService;this.token=token;}
 /** 消费资产事件。 @param authorization 授权 @param event 事件 @return 媒体 */ @PostMapping("/internal/v1/media/asset-events") public MediaView consume(@RequestHeader("Authorization")String authorization,@Valid @RequestBody AssetEvent event){authorize(authorization);return service.consume(event);}
 /** 导入旧媒体及标签。 @param authorization 授权 @param request 请求 @return 媒体 */ @PostMapping("/internal/v1/media/migrations/legacy-items") public MediaView importLegacy(@RequestHeader("Authorization")String authorization,@Valid @RequestBody LegacyMediaImport request){authorize(authorization);return service.importLegacy(request);}
 /** 查询本次旧媒体迁移证据。 @param authorization 授权 @param migrationKey 迁移键 @return 证据 */ @GetMapping("/internal/v1/media/migrations/legacy-items/{migrationKey}/evidence") public LegacyMigrationEvidence legacyMigrationEvidence(@RequestHeader("Authorization")String authorization,@PathVariable String migrationKey){authorize(authorization);return service.legacyMigrationEvidence(migrationKey);}
 /** 开始分析。 @param authorization 授权 @param id 媒体 @param request 请求 @return 分析 */ @PostMapping("/internal/v1/media/items/{id}/analyses") @ResponseStatus(HttpStatus.CREATED) public AnalysisView begin(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@Valid @RequestBody BeginAnalysis request){authorize(authorization);return service.begin(id,request);}
 /** 完成分析。 @param authorization 授权 @param id 媒体 @param request 请求 */ @PostMapping("/internal/v1/media/items/{id}/analyses/complete") @ResponseStatus(HttpStatus.NO_CONTENT) public void complete(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@Valid @RequestBody CompleteAnalysis request){authorize(authorization);service.complete(id,request);}
 /** 标记分析失败终态。 @param authorization 授权 @param id 媒体 @param request 请求 */ @PostMapping("/internal/v1/media/items/{id}/analyses/fail") @ResponseStatus(HttpStatus.NO_CONTENT) public void fail(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@Valid @RequestBody FailAnalysis request){authorize(authorization);service.fail(id,request);}
 /** 查询媒体。 @param authorization 授权 @param ownerId 所有者 @param id 标识 @return 媒体 */ @GetMapping("/internal/v1/media/items/{id}") public MediaView view(@RequestHeader("Authorization")String authorization,@RequestParam long ownerId,@PathVariable UUID id){authorize(authorization);return service.view(ownerId,id);}
 /** 删除当前所有者媒体投影。 @param authorization 授权 @param ownerId 所有者 @param id 标识 */ @DeleteMapping("/internal/v1/media/items/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@RequestHeader("Authorization")String authorization,@RequestParam long ownerId,@PathVariable UUID id){authorize(authorization);service.delete(ownerId,id);}
 /** 读取已迁移媒体内容。 @param authorization 授权 @param ownerId 所有者 @param id 标识 @param thumbnail 是否读取缩略图 @return 文件 */ @GetMapping("/internal/v1/media/items/{id}/content") public ResponseEntity<Resource> content(@RequestHeader("Authorization")String authorization,@RequestParam long ownerId,@PathVariable UUID id,@RequestParam(defaultValue="false")boolean thumbnail){authorize(authorization);var content=contentService.content(ownerId,id,thumbnail);return ResponseEntity.ok().contentType(MediaType.parseMediaType(content.mimeType())).contentLength(content.sizeBytes()).body(content.resource());}
 /** 分页查询媒体。 @param authorization 授权 @param ownerId 所有者 @param afterId 起始标识 @param includeMissing 是否包含缺失项 @param mimePrefix MIME 前缀 @param limit 页大小 @return 媒体页 */ @GetMapping("/internal/v1/media/items") public MediaPage list(@RequestHeader("Authorization")String authorization,@RequestParam long ownerId,@RequestParam(required=false)UUID afterId,@RequestParam(defaultValue="false")boolean includeMissing,@RequestParam(required=false)String mimePrefix,@RequestParam(defaultValue="50")int limit){authorize(authorization);return service.list(ownerId,afterId,includeMissing,mimePrefix,limit);}
 /** 查询 EBOOK 目录中的已迁移电子书。 @param authorization 授权 @param ownerId 所有者 @param username 用户名 @param page 页码 @param pageSize 页大小 @param keyword 关键字 @return 页面 */ @GetMapping("/internal/v1/media/ebooks") public EbookPage ebooks(@RequestHeader("Authorization")String authorization,@RequestParam long ownerId,@RequestParam String username,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="40")int pageSize,@RequestParam(defaultValue="")String keyword){authorize(authorization);return ebookService.list(ownerId,username,page,pageSize,keyword);}
 /** 同步进度。 @param authorization 授权 @param ownerId 所有者 @param id 媒体 @param request 请求 @return 进度 */ @PutMapping("/internal/v1/media/items/{id}/progress") public ProgressView progress(@RequestHeader("Authorization")String authorization,@RequestParam long ownerId,@PathVariable UUID id,@Valid @RequestBody ProgressRequest request){authorize(authorization);return service.progress(ownerId,id,request);}
 /** 开始目录扫描。 @param authorization 授权 @param request 请求 @return 扫描 */ @PostMapping("/internal/v1/media/scans") @ResponseStatus(HttpStatus.CREATED) public ScanView beginScan(@RequestHeader("Authorization")String authorization,@Valid @RequestBody BeginScan request){authorize(authorization);return service.beginScan(request);}
 /** 暂存扫描条目。 @param authorization 授权 @param id 扫描 @param request 请求 */ @PutMapping("/internal/v1/media/scans/{id}/entries") @ResponseStatus(HttpStatus.NO_CONTENT) public void stageScan(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@Valid @RequestBody StageScanEntries request){authorize(authorization);service.stageScan(id,request);}
 /** 发布扫描批次。 @param authorization 授权 @param id 扫描 @param request 请求 @return 扫描 */ @PostMapping("/internal/v1/media/scans/{id}/complete") public ScanView finishScan(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@Valid @RequestBody FinishScan request){authorize(authorization);return service.finishScan(id,request);}
 /** 查询扫描批次。 @param authorization 授权 @param id 扫描 @return 扫描 */ @GetMapping("/internal/v1/media/scans/{id}") public ScanView scan(@RequestHeader("Authorization")String authorization,@PathVariable UUID id){authorize(authorization);return service.scan(id);}
 /** 创建目录扫描任务。 @param authorization 授权 @param ownerId 所有者 @param request 请求 @return 操作 */ @PostMapping("/internal/v1/media/operations/directory-scans") @ResponseStatus(HttpStatus.ACCEPTED) public OperationView startDirectoryScan(@RequestHeader("Authorization")String authorization,@RequestParam long ownerId,@Valid @RequestBody StartDirectoryScan request){authorize(authorization);return service.startDirectoryScan(ownerId,request);}
 /** 创建媒体分析任务。 @param authorization 授权 @param id 媒体标识 @param ownerId 所有者 @param request 请求 @return 操作 */ @PostMapping("/internal/v1/media/items/{id}/analysis-operations") @ResponseStatus(HttpStatus.ACCEPTED) public OperationView startAnalysis(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@RequestParam long ownerId,@Valid @RequestBody StartAnalysis request){authorize(authorization);return service.startAnalysis(id,ownerId,request);}
 /** 查询媒体操作。 @param authorization 授权 @param id 操作 @param ownerId 所有者 @return 操作 */ @GetMapping("/internal/v1/media/operations/{id}") public OperationView operation(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@RequestParam long ownerId){authorize(authorization);return service.operation(id,ownerId);}
 /** 取消媒体操作。 @param authorization 授权 @param id 操作 @param ownerId 所有者 @return 操作 */ @PostMapping("/internal/v1/media/operations/{id}/cancel") public OperationView cancelOperation(@RequestHeader("Authorization")String authorization,@PathVariable UUID id,@RequestParam long ownerId){authorize(authorization);return service.cancelOperation(id,ownerId);}
 /** 查询媒体关系对账页。 @param authorization 授权 @param afterId 起始标识 @param limit 页大小 @return 对账页 */ @GetMapping("/internal/v1/media/reconciliation") public ReconciliationPage reconciliation(@RequestHeader("Authorization")String authorization,@RequestParam(required=false)UUID afterId,@RequestParam(defaultValue="200")int limit){authorize(authorization);return service.reconciliation(afterId,limit);}
 /** 解析旧文件分析目标。 @param authorization 授权 @param legacyId 旧文件标识 @return 分析目标 */ @GetMapping("/internal/v1/media/migrations/legacy-items/{legacyId}/analysis-target") public LegacyAnalysisTarget legacyAnalysisTarget(@RequestHeader("Authorization")String authorization,@PathVariable long legacyId){authorize(authorization);return service.legacyAnalysisTarget(legacyId);}
 private void authorize(String authorization){byte[] expected=("Bearer "+token.value()).getBytes(StandardCharsets.UTF_8);if(token.value().isBlank()||!MessageDigest.isEqual(expected,authorization.getBytes(StandardCharsets.UTF_8)))throw new SecurityException("media internal authorization failed");}
}
